import{_ as a,o as t,c as s,a3 as d}from"./chunks/framework.BNdm2jZV.js";const m=JSON.parse('{"title":"v6 Monorepo 架构","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),o={name:"guide/architecture.md"};function r(p,e,i,n,c,l){return t(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="v6-monorepo-架构" tabindex="-1">v6 Monorepo 架构 <a class="header-anchor" href="#v6-monorepo-架构" aria-label="Permalink to &quot;v6 Monorepo 架构&quot;">​</a></h1><p>Ray Template 6.0.0 把后台应用、官网文档和共享能力放到同一个 pnpm workspace。<strong>Ray Admin</strong> 是完整后台，官网则按页加载同一套组件和工具做交互示例。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ray-template/</span></span>
<span class="line"><span>├── apps/</span></span>
<span class="line"><span>│   ├── admin/          # Ray Admin：登录、会话、路由和业务页面</span></span>
<span class="line"><span>│   └── docs/           # VitePress：指南、API 与交互示例</span></span>
<span class="line"><span>├── packages/           # 两个应用共用的八个私有 workspace 包</span></span>
<span class="line"><span>├── harness/            # 任务入口与验收命令</span></span>
<span class="line"><span>└── pnpm-lock.yaml      # 工作区共用锁文件</span></span></code></pre></div><h2 id="各包负责什么" tabindex="-1">各包负责什么 <a class="header-anchor" href="#各包负责什么" aria-label="Permalink to &quot;各包负责什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>公开能力与使用方式</th></tr></thead><tbody><tr><td><code>@ray-template/utils</code></td><td>精度运算、对象和类型处理、文件工具、接收存储实现的 JSON 工具。精度运算从 <code>/precision</code> 导入。</td></tr><tr><td><code>@ray-template/composables</code></td><td>设备宽度、元素全屏、截图、打印和其他独立 Vue Hooks，例如 <code>/useElementFullscreen</code>。</td></tr><tr><td><code>@ray-template/directives</code></td><td>复制、防抖、节流、省略、水波纹等指令，可单独导入或统一注册。</td></tr><tr><td><code>@ray-template/icons</code></td><td>SVG 资源、图标名称类型和资源查找。组件和路由配置使用同一套名称。</td></tr><tr><td><code>@ray-template/ui</code></td><td>组件、样式、主题与类型。通过 <code>/table-pro</code>、<code>/barcode</code> 或 <code>/chart</code> 等入口按需导入。</td></tr><tr><td><code>@ray-template/http</code></td><td><code>createHttpClient</code> 创建实例与独立的取消器。宿主提供地址、请求头和拦截器。</td></tr><tr><td><code>@ray-template/routing</code></td><td>路由 Schema、配置校验、路由展开和菜单处理。宿主提供页面注册表。</td></tr><tr><td><code>@ray-template/admin-shell</code></td><td>布局、顶部导航、标签、设置和路由过渡。宿主提供菜单、选中状态、偏好和内容。</td></tr></tbody></table><p>共享包通过 <code>package.json</code> 的 <code>exports</code> 暴露入口，只依赖自己声明的包。<code>pnpm packages:check</code> 检查跨包导入和依赖循环。应用的登录、路由守卫、业务 API、Pinia 实例和语言加载由 <code>apps/admin</code> 负责。</p><h2 id="ray-admin-怎么组装" tabindex="-1">Ray Admin 怎么组装 <a class="header-anchor" href="#ray-admin-怎么组装" aria-label="Permalink to &quot;Ray Admin 怎么组装&quot;">​</a></h2><p><code>apps/admin/src/main.ts</code> 安装 Pinia、国际化、路由和指令。应用入口为组件提供主题、翻译、图标和列偏好存储，路由层把注册的页面交给后台外壳。登录、角色和会话由应用处理，真实业务的服务端负责接口授权。</p><p>以 TablePro 为例，组件负责展示、搜索、分页与请求状态。后台传入业务查询，文档传入可取消的模拟查询。两边从同一个入口导入：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { RTablePro } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@ray-template/ui/table-pro&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { add } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@ray-template/utils/precision&#39;</span></span></code></pre></div><p><a href="https://github.com/XiaoDaiGua-Ray/ray-template/blob/97f832c66fd112c37f09071f26955deec1d53cff/apps/admin/src/main.ts" target="_blank" rel="noreferrer">后台应用入口</a> · <a href="https://github.com/XiaoDaiGua-Ray/ray-template/blob/97f832c66fd112c37f09071f26955deec1d53cff/apps/admin/src/App.tsx" target="_blank" rel="noreferrer">应用组装</a> · <a href="https://github.com/XiaoDaiGua-Ray/ray-template/blob/97f832c66fd112c37f09071f26955deec1d53cff/docs/architecture.md" target="_blank" rel="noreferrer">完整工程地图</a></p><h2 id="文档怎样运行组件" tabindex="-1">文档怎样运行组件 <a class="header-anchor" href="#文档怎样运行组件" aria-label="Permalink to &quot;文档怎样运行组件&quot;">​</a></h2><p><code>apps/docs/examples</code> 保存实际运行的 Vue 示例。Markdown 引用同一个文件展示源码。TablePro 使用本地数据或可控的模拟请求；布局实验在独立预览框内运行，使用自己的内存路由和主题状态。</p><p><a href="./../reference/utils/core.html#交互示例">精度运算</a> · <a href="./../reference/components/barcode.html#交互示例">RBarcode</a> · <a href="./../reference/table-pro.html#交互示例">TablePro</a> · <a href="./layout.html#在线布局实验">布局实验</a></p><h2 id="构建与部署" tabindex="-1">构建与部署 <a class="header-anchor" href="#构建与部署" aria-label="Permalink to &quot;构建与部署&quot;">​</a></h2><p><code>pnpm dev</code> 启动后台，<code>pnpm docs:dev</code> 启动文档。<code>pnpm build</code> 输出后台，<code>pnpm docs:build</code> 输出文档，<code>pnpm pages:build</code> 组装两者到 <code>dist/pages</code>。官方部署地址分别是 <code>/ray-template/</code> 和 <code>/ray-template/docs/</code>。<a href="./tooling.html">构建与部署指南</a></p><p>如果当前项目基于 v5，请先看<a href="./../migration.html">版本分界</a>，再决定是否接入 v6。</p>`,17)])])}const u=a(o,[["render",r]]);export{m as __pageData,u as default};
